-- Add ML Predictions Table for Daily Inference Pipeline
-- This table stores predictions generated by the ML models

-- ML Predictions Table
CREATE TABLE IF NOT EXISTS ml_predictions (
    id SERIAL PRIMARY KEY,
    forecast_date DATE NOT NULL,
    prediction FLOAT NOT NULL,
    uncertainty FLOAT,
    lower_95 FLOAT,
    upper_95 FLOAT,
    median FLOAT,
    model_version VARCHAR(50),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(forecast_date, model_version)
);

-- Index for fast date lookups
CREATE INDEX IF NOT EXISTS idx_ml_predictions_forecast_date ON ml_predictions(forecast_date);
CREATE INDEX IF NOT EXISTS idx_ml_predictions_created_at ON ml_predictions(created_at);
CREATE INDEX IF NOT EXISTS idx_ml_predictions_model_version ON ml_predictions(model_version);

-- Add comments
COMMENT ON TABLE ml_predictions IS 'ML model predictions for solar activity';
COMMENT ON COLUMN ml_predictions.forecast_date IS 'Date being predicted';
COMMENT ON COLUMN ml_predictions.prediction IS 'Predicted sunspot number (mean)';
COMMENT ON COLUMN ml_predictions.uncertainty IS 'Prediction uncertainty (std deviation)';
COMMENT ON COLUMN ml_predictions.lower_95 IS '95% confidence interval lower bound';
COMMENT ON COLUMN ml_predictions.upper_95 IS '95% confidence interval upper bound';
COMMENT ON COLUMN ml_predictions.median IS 'Median prediction';
COMMENT ON COLUMN ml_predictions.model_version IS 'Version of model used';
COMMENT ON COLUMN ml_predictions.created_at IS 'When prediction was generated';

-- View for latest predictions
CREATE OR REPLACE VIEW ml_predictions_latest AS
SELECT DISTINCT ON (forecast_date)
    forecast_date,
    prediction,
    uncertainty,
    lower_95,
    upper_95,
    median,
    model_version,
    created_at
FROM ml_predictions
ORDER BY forecast_date, created_at DESC;

-- View for prediction accuracy (when actual data is available)
CREATE OR REPLACE VIEW ml_prediction_accuracy AS
SELECT
    p.forecast_date,
    p.prediction,
    p.uncertainty,
    o.ssn as actual,
    ABS(p.prediction - o.ssn) as absolute_error,
    CASE
        WHEN o.ssn != 0 THEN ABS((p.prediction - o.ssn) / o.ssn) * 100
        ELSE NULL
    END as percentage_error,
    CASE
        WHEN o.ssn BETWEEN p.lower_95 AND p.upper_95 THEN true
        ELSE false
    END as within_95_ci,
    p.model_version,
    p.created_at as prediction_time
FROM ml_predictions p
LEFT JOIN solar_observations o ON p.forecast_date = o.observation_date
WHERE o.ssn IS NOT NULL
ORDER BY p.forecast_date DESC;

-- Function to get prediction for a specific date
CREATE OR REPLACE FUNCTION get_prediction(target_date DATE)
RETURNS TABLE (
    forecast_date DATE,
    prediction FLOAT,
    uncertainty FLOAT,
    lower_95 FLOAT,
    upper_95 FLOAT,
    median FLOAT,
    model_version VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.forecast_date,
        p.prediction,
        p.uncertainty,
        p.lower_95,
        p.upper_95,
        p.median,
        p.model_version
    FROM ml_predictions p
    WHERE p.forecast_date = target_date
    ORDER BY p.created_at DESC
    LIMIT 1;
END;
$$ LANGUAGE plpgsql;

-- Function to calculate model performance metrics
CREATE OR REPLACE FUNCTION calculate_model_metrics(
    start_date DATE DEFAULT CURRENT_DATE - INTERVAL '30 days',
    end_date DATE DEFAULT CURRENT_DATE
)
RETURNS TABLE (
    model_version VARCHAR,
    num_predictions BIGINT,
    rmse FLOAT,
    mae FLOAT,
    mape FLOAT,
    coverage_95 FLOAT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.model_version,
        COUNT(*) as num_predictions,
        SQRT(AVG(POWER(p.prediction - o.ssn, 2))) as rmse,
        AVG(ABS(p.prediction - o.ssn)) as mae,
        AVG(CASE
            WHEN o.ssn != 0 THEN ABS((p.prediction - o.ssn) / o.ssn) * 100
            ELSE NULL
        END) as mape,
        AVG(CASE
            WHEN o.ssn BETWEEN p.lower_95 AND p.upper_95 THEN 1.0
            ELSE 0.0
        END) * 100 as coverage_95
    FROM ml_predictions p
    INNER JOIN solar_observations o ON p.forecast_date = o.observation_date
    WHERE p.forecast_date BETWEEN start_date AND end_date
    GROUP BY p.model_version
    ORDER BY p.model_version;
END;
$$ LANGUAGE plpgsql;

-- Grant permissions
GRANT SELECT, INSERT, UPDATE ON ml_predictions TO PUBLIC;
GRANT SELECT ON ml_predictions_latest TO PUBLIC;
GRANT SELECT ON ml_prediction_accuracy TO PUBLIC;
GRANT USAGE, SELECT ON SEQUENCE ml_predictions_id_seq TO PUBLIC;

