-- Success message
DO $$
BEGIN
    RAISE NOTICE 'ML predictions table created successfully';
    RAISE NOTICE 'Views created: ml_predictions_latest, ml_prediction_accuracy';
    RAISE NOTICE 'Functions created: get_prediction(), calculate_model_metrics()';
END $$;
